import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import '../../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../data/models/update_password.dart';import '../../data/models/update_user.dart';import '../../data/Sources/user_data_sources.dart';import '../../data/repositories/user_repo.dart';class UserRepoImp extends UserRepo {  @override  Future<Either<Failure, UpdateUser>> updateUser(UpdateUser updateUser) async {    try {      final response =          await UserDataSources.updateUserData(updateUser: updateUser);      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }  @override  Future<Either<Failure, bool>> updatePassword(      UpdatePassword updatePassword) async {    try {      final response =          await UserDataSources.updatePassword(updateUser: updatePassword);      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }}